describe('User Mention in Comment', () => {
    beforeEach(() => {
        cy.visit('/comments'); // Navigate to the comments page
        cy.login('testuser', 'password'); // Assuming a login function exists
    });

    it('should allow a user to mention another user in a comment', () => {
        cy.get('textarea.comment-input').type('Hello @john_doe, how are you?');
        cy.get('button.submit-comment').click();
        cy.get('.comment').should('contain', '@john_doe');
        cy.get('.comment').should('contain', 'Hello @john_doe, how are you?');
    });

    it('should not allow mentioning a non-existent user', () => {
        cy.get('textarea.comment-input').type('Hello @non_existent_user, how are you?');
        cy.get('button.submit-comment').click();
        cy.get('.error-message').should('be.visible').and('contain', 'User not found');
    });
});
